&=\hat{\mathbf{i}}+2 \hat{\mathbf{j}}+2 \hat{\mathbf{k}}
\end{aligned}$
Now, required unit vector $=\frac{\hat{\mathbf{i}}+2 \hat{\mathbf{j}}+2 \hat{\mathbf{k}}}{\sqrt{1+4+4}}=\frac{1}{3}(\hat{\mathbf{i}}+2 \hat{\mathbf{j}}+2 \hat{\mathbf{k}})$

Let $=\hat{\mathfrak{i}}-\hat{\mathfrak{j}}$ and $\mathrm{b}=\hat{\mathfrak{i}}-2 \hat{\mathfrak{j}}$
The required vector is along the vector $\mathbf{a} \times(\mathbf{a} \times \mathbf{b})=(\mathbf{a} \cdot \mathbf{b}) \mathbf{a}-(\mathbf{a} \cdot \mathbf{a}) \mathbf{b}$
\begin{aligned}
&=3(\hat{\mathbf{i}}-\hat{\mathbf{j}})-2(\hat{\mathbf{i}}-2 \hat{\mathbf{j}}) \\
&=3 \hat{\mathbf{i}}-3 \hat{\mathbf{j}}-2 \hat{\mathbf{i}}+4 \hat{\mathbf{j}}=\hat{\mathbf{i}}+\hat{\mathbf{j}}
\end{aligned}

Hence, required vectors are given by $\pm \frac{(\hat{\mathbf{i}}+\hat{\mathfrak{j}})}{\sqrt{1+1}}=\pm \cdot \frac{1}{\sqrt{2}}(\hat{\mathbf{i}}+\hat{\mathbf{j}})$

Let $\mathbf{a}=3 \mathbf{i}+\mathbf{j}+2 \mathbf{k}$ and $\mathbf{b}=\mathbf{i}+\mathbf{j}+2 \mathbf{k}$
